<?php
session_start();require '../config/database.php'; require '../lib_security.php';if(!isset($_SESSION['user'])||$_SESSION['user']['role']!=='admin'){header('Location: ../login.php');exit;}
$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){ verifyCsrf();$sid=(int)$_POST['student_id'];$card='ID-IMCB-'.date('Y').'-'.str_pad((string)$sid,5,'0',STR_PAD_LEFT);$q=$pdo->prepare('INSERT INTO student_id_cards(student_id,card_no,issue_date,valid_until,status) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE card_no=VALUES(card_no),issue_date=VALUES(issue_date),valid_until=VALUES(valid_until),status="active"');$q->execute([$sid,$card,date('Y-m-d'),date('Y-m-d',strtotime('+1 year')),'active']);$msg='ID card issued/renewed.';}
$rows=$pdo->query('SELECT st.id,st.roll_no,st.semester_or_year,u.name,p.name program_name,c.card_no,c.valid_until,c.status FROM students st JOIN users u ON u.id=st.user_id JOIN programs p ON p.id=st.program_id LEFT JOIN student_id_cards c ON c.student_id=st.id ORDER BY u.name')->fetchAll();$pageTitle='Student ID Cards';require '../includes/header.php';?><div class="container-fluid"><div class="row"><aside class="col-md-2 sidebar py-4"><h6 class="px-3 text-muted">ADMIN MENU</h6><a href="../admin.php">Dashboard</a><a class="active" href="id_cards.php">Student ID Cards</a><a href="documents.php">Document Verification</a></aside><main class="col-md-10 p-4"><h2 class="fw-bold">Student ID Cards</h2><?php if($msg):?><div class="alert alert-success"><?=htmlspecialchars($msg)?></div><?php endif;?><div class="card shadow-sm border-0"><div class="card-body"><div class="table-responsive"><table class="table"><thead><tr><th>Student</th><th>Roll No</th><th>Program</th><th>Card No</th><th>Valid Until</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['roll_no'])?></td><td><?=htmlspecialchars($r['program_name'])?></td><td><?=htmlspecialchars($r['card_no']??'Not issued')?></td><td><?=htmlspecialchars($r['valid_until']??'—')?></td><td><form method="post" class="d-inline"><?php echo csrfField(); ?><input type="hidden" name="student_id" value="<?=$r['id']?>"><button class="btn btn-sm btn-primary">Issue / Renew</button></form> <a target="_blank" class="btn btn-sm btn-outline-secondary" href="../id_card.php?student_id=<?=$r['id']?>">Print</a></td></tr><?php endforeach;?></tbody></table></div></div></div></main></div></div><?php require '../includes/footer.php';?>
